/* ===================== i18n: the Arabic version ===================== */
'use strict';
// The page is written in Hebrew, the default. With 'lang=ar' in the address ('#lang=ar', '#polls&lang=ar') or after
// the reader picks العربية in the header (kept in this browser), every UI string goes through t(): the Hebrew text
// is the key into AR, the dictionary at the end of this file, and {name} marks a value filled in at render time,
// so the word order can differ between the languages. A string missing from AR stays in Hebrew and is listed in
// I18N.missing. In Hebrew t() returns its key with the values filled in, so nothing changes for Hebrew readers.
// Names that come with the data (lists, localities, regions, pollsters) are put into Arabic once, as each file
// loads (i18nCore, i18nPolls, ...): party names from AR_PARTY, locality names from data/names_ar.json (CBS code ->
// Arabic name, built by pipeline/build_names_ar.py; a locality without one keeps its Hebrew name).
// Numbers keep the Western digits and separators of the Hebrew page (as Arabic media in Israel write them); a date
// with a month name is written with 'ar-u-nu-latn' (27 أكتوبر 2026), a day.month date stays 27.10 as in the text.
// Switching the language reloads the page in the other language.
const I18N = (() => {
  const KEY = 'kalpi26.lang';
  const fromHash = () => { const m = /(?:^#|&)lang=(he|ar)(?=&|$)/.exec(location.hash || ''); return m ? m[1] : null; };
  let stored = null;
  try { stored = localStorage.getItem(KEY); } catch (e) { /* storage blocked */ }
  return { KEY, lang: fromHash() || (stored === 'ar' ? 'ar' : 'he'), missing: new Set(), loc: null };
})();
const AR_ON = I18N.lang === 'ar';
// the tab named in the address without the language part ('polls' from '#polls&lang=ar'); the language part that
// keeps an Arabic link Arabic when the tab changes (none in Hebrew, so a Hebrew address is unchanged)
I18N.tabHash = () => (location.hash || '').replace(/^#/, '').split('&').filter(x => x && !/^lang=/.test(x))[0] || '';
I18N.hashTail = () => (AR_ON ? '&lang=ar' : '');

function t(he, vars) {
  let s = he;
  if (AR_ON) {
    const a = AR[he];
    // an entry that is a function builds the sentence itself (the Arabic noun agrees with the number)
    if (typeof a === 'function') return a(vars || {});
    if (a != null) s = a; else if (/[֐-׿]/.test(he)) I18N.missing.add(he);
  }
  return vars ? s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : s;
}
// a list name, a locality name: the Arabic when there is one, else the Hebrew
const tp = he => (AR_ON && he != null && AR_PARTY[String(he).trim()]) || he;
const tLoc = (code, he) => (AR_ON && I18N.loc && code != null && I18N.loc[String(code)]) || he;
// 'א, ב וג' / 'أ، ب وج' (the Arabic conjunction is written joined to the next word, also before a number)
const arJoin = a => (a.length > 1 ? a.slice(0, -1).join('، ') + ' و' + a[a.length - 1] : a[0] || '');
// a date with a month name in the page's language (a day.month date is formatted 'he-IL' in both: 27.10)
const DATE_LOCALE = AR_ON ? 'ar-u-nu-latn' : 'he-IL';
// canvas text measurement in the font the labels are drawn in
const CANVAS_FONT = AR_ON ? '"IBM Plex Sans Arabic", "IBM Plex Sans Hebrew", "Noto Sans Arabic", sans-serif'
  : '"IBM Plex Sans Hebrew", "Arial Hebrew", sans-serif';
// room for the Arabic font's taller marks (hamza) and deeper descenders where a chart label sits at the SVG's edge
const AR_PAD = AR_ON ? 3 : 0;

/* ---------- the page chrome: the header, the tabs, the footer, and the language switch ---------- */
I18N.setLang = l => {
  try { localStorage.setItem(I18N.KEY, l); } catch (e) { /* the address carries it */ }
  const tab = I18N.tabHash(), h = '#' + [tab, l === 'ar' ? 'lang=ar' : ''].filter(Boolean).join('&');
  try { history.replaceState(null, '', h === '#' ? location.pathname + location.search : h); } catch (e) { location.hash = h; }
  location.reload();
};
I18N.chrome = () => {
  const root = document.querySelector('div[dir="rtl"]');
  const mast = document.querySelector('.mast');
  if (mast && !mast.querySelector('.lang-sw')) {
    const bar = document.createElement('div');
    bar.className = 'wrap lang-bar';
    bar.innerHTML = `<div class="lang-sw" role="group" aria-label="${AR_ON ? 'اللغة' : 'שפה'}">`
      + `<button type="button" lang="he" data-lang="he" aria-pressed="${!AR_ON}">עברית</button>`
      + `<button type="button" lang="ar" data-lang="ar" aria-pressed="${AR_ON}">العربية</button></div>`;
    mast.insertBefore(bar, mast.firstChild);
    bar.addEventListener('click', e => { const b = e.target.closest('[data-lang]'); if (b && b.dataset.lang !== I18N.lang) I18N.setLang(b.dataset.lang); });
  }
  if (!AR_ON) return;
  document.documentElement.lang = 'ar';
  if (root) root.lang = 'ar';
  document.title = AR.__title;
  const font = document.createElement('link');
  font.rel = 'stylesheet';
  font.href = 'https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=Changa:wght@500;600;700&display=swap';
  // the chart gutters are measured on canvas: redraw once the Arabic fonts are in
  font.onload = () => { if (document.fonts) document.fonts.ready.then(() => { if (S.core && typeof rerenderAll === 'function') rerenderAll(); }); };
  document.head.appendChild(font);
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  set('.brand h1', AR.__brand);
  set('.brand p', t('הבחירות לכנסת ה-26: ממוצע סקרים, תרחישי קואליציה ותוצאות חמש מערכות הבחירות האחרונות, עד רמת הקלפי הבודדת. בדגש על החברה הערבית.'));
  set('.cd-lbl', t('ימים לבחירות'));
  set('.cd-date', t('<b>יום שלישי, 27 באוקטובר 2026</b>הקלפיות פתוחות 07:00–22:00<br><span id="cd-elig">כ-7.34&nbsp;מיליון בעלי זכות בחירה · 38&nbsp;רשימות</span>'));
  const nav = document.querySelector('nav.tabs'); if (nav) nav.setAttribute('aria-label', t('מדורים'));
  document.querySelectorAll('.tab').forEach(b => {
    const pill = b.querySelector('.pill');
    b.textContent = t([...b.childNodes].filter(n => n.nodeType === 3).map(n => n.textContent).join('').trim());
    if (pill) { if (/[\u0590-\u05FF]/.test(pill.textContent)) pill.textContent = t(pill.textContent); b.appendChild(pill); }
  });
  set('#loading', t('טוען נתונים רשמיים…'));
  set('.disclaimer', t('דמו לתצוגה. תוצאות העבר הן ספירות רשמיות של ועדת הבחירות המרכזית (קובצי תוצאות לפי קלפי), מאומתות מול הסיכומים הארציים הרשמיים. נתוני הסקרים נלקחו מסקרים שפורסמו, עם קישור לדיווח הרשמי לוועדת הבחירות כשנמצא. פילוח מגזרי, מעברי קולות וסימולציות מסומנים כאומדן.'));
};
// The statutory notice of the poll ban (Propaganda Methods Law §16ה(ח)) in the page's language; the Arabic page
// carries the Hebrew wording under it as well.
I18N.banNotice = el => {
  if (!AR_ON) { el.textContent = BAN_NOTICE; return; }
  el.innerHTML = `<span>${esc(t(BAN_NOTICE))}</span><span class="ban-he" lang="he">${esc(BAN_NOTICE)}</span>`;
};

/* ---------- the data's own names, put into Arabic as each file loads ---------- */
// a CBS-coded name with an Arabic version, else the Hebrew one; the Hebrew stays in name_he for the search boxes
function i18nCore(core) {
  if (!AR_ON || !core) return core;
  const tx = s => (s == null ? s : t(s));
  core.elections.forEach(e => {
    e.label = tx(e.label); e.short = tx(e.short); e.bloc_note = tx(e.bloc_note);
    e.parties.forEach(p => { p.name_he = p.name; p.name = tp(p.name); });
  });
  Object.values(core.families).forEach(f => { f.name_he = f.name; f.name = tx(f.name); });
  Object.values(core.sectors).forEach(s => { s.name = tx(s.name); s.desc = tx(s.desc); });
  ['arab_regions', 'druze_regions'].forEach(k => Object.keys(core[k] || {}).forEach(r => { core[k][r] = tx(core[k][r]); }));
  Object.keys(core.mixed_cities || {}).forEach(c => { core.mixed_cities[c] = tLoc(c, core.mixed_cities[c]); });
  core.localities.forEach(l => { l.name_he = l.name; l.name = tLoc(l.code, l.name); });
  return core;
}
function i18nPolls(P) {
  if (!AR_ON || !P) return P;
  P.parties.forEach(p => { p.name_he = p.name; p.name = tp(p.name); p.leader = t(p.leader); });
  P.polls.forEach(q => { q.house_he = t(q.house_he); q.outlet_he = t(q.outlet_he); if (q.pollster_he) q.pollster_he = t(q.pollster_he); });
  if (P.source) P.source = t(P.source);
  return P;
}
function i18nFinalPolls(F) {
  if (!AR_ON || !F) return F;
  F.source = t(F.source);
  F.elections.forEach(e => e.polls.forEach(q => { if (q.pollster_he) q.pollster_he = t(q.pollster_he); }));
  return F;
}
// the election-day Arab section's 2022 base: regions, kinds and every locality (a mixed city's entry by its city)
function i18nArabDay(B) {
  if (!AR_ON || !B) return B;
  ['region_names', 'kind_names', 'group_names', 'group_short', 'sub_names'].forEach(k => Object.keys(B[k] || {}).forEach(r => { B[k][r] = t(B[k][r]); }));
  B.localities.forEach(b => {
    b.name_he = b.name; b.city_he = b.city;
    if (b.kind === 'mixed_arab') { b.city = tLoc(b.code, b.city); b.name = b.city; } else { b.name = tLoc(b.code, b.name); b.city = tLoc(b.code, b.city); }
    if (b.top_other22) b.top_other22.name = tp(b.top_other22.name);
  });
  return B;
}
// a replay or a feed frame: list names, frame labels ('נספרו 30%') and notes
function i18nFrames(frames) {
  (frames || []).forEach(F => {
    if (!F) return;
    if (F.label) F.label = t(F.label.replace(/^נספרו (\d+)%$/, 'נספרו {n}%'), { n: (/(\d+)%$/.exec(F.label) || [])[1] });
    (F.lists || []).forEach(l => { l.name = tp(l.name); });
  });
}
function i18nReplay(doc) {
  if (!AR_ON || !doc) return doc;
  ['note', 'accuracy_note'].forEach(k => { if (doc[k]) doc[k] = t(doc[k]); });
  Object.values(doc.replays || {}).forEach(R => {
    ['label', 'note'].forEach(k => { if (R[k]) R[k] = t(R[k]); });
    i18nFrames(R.frames);
    if (R.exit_polls) { if (R.exit_polls.note) R.exit_polls.note = t(R.exit_polls.note); (R.exit_polls.polls || []).forEach(p => { p.outlet = t(p.outlet); }); }
  });
  return doc;
}
// the live feed's results.json: the lists and the labels the feed writes; free text the operator types stays as typed
function i18nLive(R) {
  if (!AR_ON || !R) return R;
  if (R.source_label) R.source_label = t(R.source_label);
  if (R.accuracy_note) R.accuracy_note = t(R.accuracy_note);
  i18nFrames([R.frame]);
  return R;
}
function i18nTurnoutHistory(H) {
  if (!AR_ON || !H) return H;
  Object.values(H.elections || {}).forEach(e => { if (e.label) e.label = t(e.label); });
  return H;
}


/* ---------- counted nouns ---------- */
// Arabic number agreement: 1 'مقعد واحد', 2 'مقعدان', 3–10 '5 مقاعد', 11–99 '61 مقعدًا', from 100 by the last two
// digits ('100 مقعد', '105 مقاعد'); a fraction takes the singular ('2.4 مقعد'). n may come formatted ('1,234'), and
// shown, when given, is what is written for the number. Forms: [one, two, plural, accusative singular, singular].
function arN(n, f, shown) {
  const s = shown != null ? String(shown) : String(n), x = +String(n).replace(/,/g, '');
  if (!Number.isFinite(x)) return `${s} ${f[4]}`;
  if (!Number.isInteger(x)) return `${s} ${f[4]}`;
  if (x === 1) return f[0];
  if (x === 2) return f[1];
  const r = x % 100;
  return `${s} ${r >= 3 && r <= 10 ? f[2] : r >= 11 ? f[3] : f[4]}`;
}
// the noun alone, for a count written elsewhere ('<b>5</b> بلدات')
function arNoun(n, f) { const x = +String(n).replace(/,/g, ''), r = x % 100; return x === 1 ? f[4] : x === 2 ? f[1] : r >= 3 && r <= 10 ? f[2] : r >= 11 ? f[3] : f[4]; }
